package com.bank.ring;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.Logger;

// Finds the LCA of many nodes by counting distinct targets per subtree.
public class MultiLcaService {

    private static final Logger log = Logger.getLogger(MultiLcaService.class.getName());

    private Set<EmployeeNode> targets;
    private int distinctCount;
    private EmployeeNode result; // deepest node covering all targets

    public EmployeeNode lcaOfMany(EmployeeNode root, List<EmployeeNode> nodes) {
        if (nodes == null || nodes.isEmpty()) {
            throw new IllegalArgumentException("Target list must be non-empty");
        }
        this.targets = new HashSet<>(nodes);      // deduplicate
        this.distinctCount = targets.size();
        this.result = null;
        countTargets(root);
        return result;
    }

    // Returns how many distinct targets are in this subtree (incl. node).
    private int countTargets(EmployeeNode node) {
        if (node == null) {
            return 0;
        }
        int left = countTargets(node.getLeft());
        int right = countTargets(node.getRight());
        int self = targets.contains(node) ? 1 : 0;
        int total = left + right + self;

        // Post-order: the FIRST node (deepest) whose subtree covers all.
        if (total == distinctCount && result == null) {
            result = node;
        }
        return total;
    }

    public EmployeeNode findRingManager(EmployeeNode root, List<EmployeeNode> ring) {
        EmployeeNode manager = lcaOfMany(root, ring);
        log.info(() -> "Lowest manager overseeing the entire flagged group is "
                + (manager != null ? manager.getName() : "none"));
        return manager;
    }
}
