package com.bank.ring;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class MultiLcaDemo {

    private static final Logger log = Logger.getLogger(MultiLcaDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Fraud Ring Common Manager (LCA of N)");

        //                 CEO
        //               /      \
        //         RegionHead    AuditHead
        //          /    \           \
        //      Rajesh  Priya       Arjun
        //       /
        //    Meena
        EmployeeNode ceo = new EmployeeNode("CEO");
        EmployeeNode regionHead = new EmployeeNode("RegionHead");
        EmployeeNode auditHead = new EmployeeNode("AuditHead");
        EmployeeNode rajesh = new EmployeeNode("Rajesh");
        EmployeeNode priya = new EmployeeNode("Priya");
        EmployeeNode arjun = new EmployeeNode("Arjun");
        EmployeeNode meena = new EmployeeNode("Meena");
        ceo.setLeft(regionHead);
        ceo.setRight(auditHead);
        regionHead.setLeft(rajesh);
        regionHead.setRight(priya);
        auditHead.setRight(arjun);
        rajesh.setLeft(meena);

        MultiLcaService service = new MultiLcaService();
        // flagged group (with a duplicate Priya) all under RegionHead
        service.findRingManager(ceo, List.of(meena, priya, rajesh, priya)); // RegionHead
        // group spanning both sides → CEO
        service.findRingManager(ceo, List.of(meena, arjun));                // CEO
    }
}
